INSERT INTO sys_menu(parent_id,path,name,component,title,hide,disable,sort,type,permission,icon,created_at,updated_at,created_by) SELECT m.id,N'',N'SystemLoginLogDelete',N'',N'删除登录日志',1,0,1,3,N'system:login-log:delete',N'',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM sys_menu m WHERE m.permission=N'system:login-log:list' AND m.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission=N'system:login-log:delete' AND deleted_at IS NULL);
INSERT INTO sys_menu(parent_id,path,name,component,title,hide,disable,sort,type,permission,icon,created_at,updated_at,created_by) SELECT m.id,N'',N'SystemLoginLogClear',N'',N'清空登录日志',1,0,2,3,N'system:login-log:clear',N'',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM sys_menu m WHERE m.permission=N'system:login-log:list' AND m.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission=N'system:login-log:clear' AND deleted_at IS NULL);
INSERT INTO sys_menu(parent_id,path,name,component,title,hide,disable,sort,type,permission,icon,created_at,updated_at,created_by) SELECT m.id,N'',N'SystemLoginLogUnlock',N'',N'解锁登录账号',1,0,3,3,N'system:login-log:unlock',N'',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 FROM sys_menu m WHERE m.permission=N'system:login-log:list' AND m.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM sys_menu WHERE permission=N'system:login-log:unlock' AND deleted_at IS NULL);
INSERT INTO sys_role_menu(role_id,menu_id) SELECT 1,m.id FROM sys_menu m WHERE m.permission IN (N'system:login-log:delete',N'system:login-log:clear',N'system:login-log:unlock') AND m.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM sys_role_menu x WHERE x.role_id=1 AND x.menu_id=m.id);
INSERT INTO sys_menu_api(menu_id,api_id) SELECT m.id,a.id FROM sys_menu m JOIN sys_api a ON ((m.permission=N'system:login-log:delete' AND a.path=N'/api/sysLoginLog/delete' AND a.method=N'DELETE') OR (m.permission=N'system:login-log:clear' AND a.path=N'/api/sysLoginLog/clear' AND a.method=N'POST') OR (m.permission=N'system:login-log:unlock' AND a.path=N'/api/sysLoginLog/unlock' AND a.method=N'POST')) WHERE m.permission IN (N'system:login-log:delete',N'system:login-log:clear',N'system:login-log:unlock') AND a.deleted_at IS NULL AND NOT EXISTS (SELECT 1 FROM sys_menu_api x WHERE x.menu_id=m.id AND x.api_id=a.id);
INSERT INTO sys_casbin_rule(ptype,v0,v1,v2,v3,v4,v5) SELECT N'p',CONCAT(N'role_',rm.role_id),a.path,a.method,N'*',N'',N'' FROM sys_role_menu rm JOIN sys_menu m ON m.id=rm.menu_id JOIN sys_menu_api ma ON ma.menu_id=m.id JOIN sys_api a ON a.id=ma.api_id WHERE m.permission IN (N'system:login-log:delete',N'system:login-log:clear',N'system:login-log:unlock') AND NOT EXISTS (SELECT 1 FROM sys_casbin_rule c WHERE c.ptype=N'p' AND c.v0=CONCAT(N'role_',rm.role_id) AND c.v1=a.path AND c.v2=a.method AND c.v3=N'*');
